python3 -c "
import os
font_dirs = ['/usr/share/fonts', '/usr/local/share/fonts', os.path.expanduser('~/.fonts')]
for d in font_dirs:
    if os.path.exists(d):
        for root, dirs, files in os.walk(d):
            for f in files:
                if f.endswith(('.ttf', '.otf', '.ttc')):
                    p = os.path.join(root, f)
                    if any(k in p.lower() for k in ['noto','sans','roboto','inter','helvetica','arial','dejavu','free']):
                        print(p)
" | sort | head -40
